def findGCD(nums):
    # Step 1: Find the smallest and largest numbers in the array
    smallest = nums[0]
    largest = nums[0]
    for num in nums:
        if num < smallest:
            smallest = num
        if num > largest:
            largest = num

    # Step 2: Compute GCD using Euclidean algorithm
    def gcd(a, b):
        # Continue until b is zero
        while b != 0:
            a, b = b, a % b
        return a

    return gcd(smallest, largest)
